#include <stdio.h>

int main(void) {
    int w, h;
    scanf("%d %d", &w, &h);
    for (int row = 0; row < h; row++) {
        for (int col = 0; col < w; col++) {
            int border = row == 0 || row == h - 1 || col == 0 || col == w - 1;
            printf("%c", border ? '#' : ' ');
        }
        printf("\n");
    }
    return 0;
}

