#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int count = 0;
    for (int k = 2; k <= n; k++) {
        int prime = 1;
        for (int d = 2; d * d <= k; d++) {
            if (k % d == 0) {
                prime = 0;
                break;
            }
        }
        if (prime) {
            if (count > 0) {
                printf(" ");
            }
            printf("%d", k);
            count++;
        }
    }
    printf("\n%d\n", count);
    return 0;
}

